function validate([nums, start, goal]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value in nums is an integer between -10^9 and 10^9.';
  if (new Set(nums).size !== nums.length) return 'The values in nums must be distinct.';
  if (!Number.isInteger(start) || start < 0 || start > 1000) return 'start is an integer between 0 and 1000.';
  if (!Number.isInteger(goal) || goal < -1e9 || goal > 1e9) return 'goal is an integer between -10^9 and 10^9.';
  if (start === goal) return 'start and goal must differ.';
  return null;
}

