function minimumOperations(nums, start, goal) {
  const visited = new Array(1001).fill(false);
  visited[start] = true;
  let queue = [start];
  let steps = 0;

  while (queue.length > 0) {
    steps++;
    const next = [];
    for (const x of queue) {
      for (const num of nums) {
        for (const y of [x + num, x - num, x ^ num]) {
          if (y === goal) {
            return steps;
          }
          if (y >= 0 && y <= 1000 && !visited[y]) {
            visited[y] = true;
            next.push(y);
          }
        }
      }
    }
    queue = next;
  }
  return -1;
}

