function minimumOperations(nums, start, goal) {
  // Relax distances over the 1001 in-range values until nothing improves, then try one last move to goal.
  const dist = new Array(1001).fill(Infinity);
  dist[start] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let x = 0; x <= 1000; x++) {
      if (dist[x] === Infinity) continue;
      for (const v of nums) {
        for (const y of [x + v, x - v, x ^ v]) {
          if (y >= 0 && y <= 1000 && dist[x] + 1 < dist[y]) { dist[y] = dist[x] + 1; changed = true; }
        }
      }
    }
  }
  let best = goal >= 0 && goal <= 1000 ? dist[goal] : Infinity;
  for (let x = 0; x <= 1000; x++) {
    if (dist[x] === Infinity) continue;
    for (const v of nums) if (x + v === goal || x - v === goal || (x ^ v) === goal) best = Math.min(best, dist[x] + 1);
  }
  return best === Infinity ? -1 : best;
}

