function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const used = new Set();
  const nums = [];
  if (size === 'large') {
    const n = int(900, 1000);
    while (nums.length < n) {
      const v = rand() < 0.03 ? int(-2000, 2000) : int(-1e9, 1e9);
      if (!used.has(v)) { used.add(v); nums.push(v); }
    }
    const start = int(0, 1000);
    let goal = rand() < 0.5 ? int(0, 1000) : int(0, 1000) + nums[int(0, n - 1)];
    if (goal > 1e9 || goal < -1e9 || goal === start) goal = start === 0 ? 1 : start - 1;
    return [nums, start, goal];
  }
  const n = int(1, 5);
  const span = rand() < 0.5 ? 12 : 60;
  while (nums.length < n) {
    const v = rand() < 0.1 ? int(-1e9, 1e9) : int(-span, span);
    if (!used.has(v)) { used.add(v); nums.push(v); }
  }
  const start = rand() < 0.2 ? int(0, 1000) : int(0, 40);
  let goal = start;
  while (goal === start) goal = rand() < 0.2 ? int(-1100, 1100) : int(-60, 100);
  return [nums, start, goal];
}
